compose_surface_node.raw_surface:
{
  "root": "root",
  "components": [
    {
      "id": "root",
      "type": "Column",
      "children": [
        "title",
        "summary",
        "calendar",
        "ratings_heading",
        "ratings_list",
        "actions_heading",
        "action_buttons"
      ]
    },
    {
      "id": "title",
      "type": "Text",
      "variant": "heading",
      "text": {
        "$bind": "/title"
      }
    },
    {
      "id": "summary",
      "type": "Text",
      "variant": "body",
      "text": {
        "$bind": "/summary"
      }
    },
    {
      "id": "calendar",
      "type": "Calendar",
      "title": "Trip Itinerary",
      "events": {
        "$bind": "/calendar_events"
      },
      "month": {
        "$bind": "/calendar_month"
      }
    },
    {
      "id": "ratings_heading",
      "type": "Text",
      "variant": "heading",
      "text": "Accommodation Reviews"
    },
    {
      "id": "ratings_list",
      "type": "List",
      "children": [
        "r0",
        "r1",
        "r2"
      ]
    },
    {
      "id": "r0",
      "type": "Rating",
      "label": "Hotel Nikko Osaka (Shinsaibashi)",
      "value": {
        "$bind": "/rating_0_value"
      },
      "max": 5,
      "count": {
        "$bind": "/rating_0_count"
      }
    },
    {
      "id": "r1",
      "type": "Rating",
      "label": "Cross Hotel Osaka (Dotonbori)",
      "value": {
        "$bind": "/rating_1_value"
      },
      "max": 5,
      "count": {
        "$bind": "/rating_1_count"
      }
    },
    {
      "id": "r2",
      "type": "Rating",
      "label": "Hotel Granvia Osaka (Umeda)",
      "value": {
        "$bind": "/rating_2_value"
      },
      "max": 5,
      "count": {
        "$bind": "/rating_2_count"
      }
    },
    {
      "id": "actions_heading",
      "type": "Text",
      "variant": "heading",
      "text": "Explore Details"
    },
    {
      "id": "action_buttons",
      "type": "Row",
      "children": [
        "b0",
        "b1"
      ]
    },
    {
      "id": "b0",
      "type": "Button",
      "label": "View Osaka Castle Details",
      "onPress": {
        "action": "request_data"
      }
    },
    {
      "id": "b1",
      "type": "Button",
      "label": "View Kyoto Itinerary",
      "onPress": {
        "action": "request_data"
      }
    }
  ]
}
